import{c as e,Q as t,j as s,m as n}from"./chunks/framework.DxgWTcNC.js";const u=JSON.parse('{"title":"Analysis: From aaa to a Clean Call Graph","description":"","frontmatter":{},"headers":[],"relativePath":"part1/05-analysis-pipeline.md","filePath":"part1/05-analysis-pipeline.md","lastUpdated":null}'),o={name:"part1/05-analysis-pipeline.md"};function i(d,a,l,c,p,r){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="analysis-from-aaa-to-a-clean-call-graph" tabindex="-1">Analysis: From <code>aaa</code> to a Clean Call Graph <a class="header-anchor" href="#analysis-from-aaa-to-a-clean-call-graph" aria-label="Permalink to &quot;Analysis: From \`aaa\` to a Clean Call Graph&quot;">​</a></h1><p>Loading a binary gives you raw bytes mapped at addresses. Analysis turns that into functions, basic blocks, cross-references, strings, and a call graph you can navigate. Radare2&#39;s analysis is layered: each <code>a*</code> command runs a different pass with different cost and different risk of being wrong. This chapter explains the layers, the order they run in, and which flags to enable or disable for which kind of binary.</p><h2 id="the-a-command-family" tabindex="-1">The <code>a</code> command family <a class="header-anchor" href="#the-a-command-family" aria-label="Permalink to &quot;The \`a\` command family&quot;">​</a></h2><p><code>a?</code> lists the analysis subsystem. The headline commands:</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>aa</code></td><td>analyse all (functions + basic blocks + symbols), default level</td></tr><tr><td><code>aaa</code></td><td>aa + extra passes (calls, code refs, types, jumps from imports)</td></tr><tr><td><code>aaaa</code></td><td>aaa + experimental passes (might rename functions; can be wrong)</td></tr><tr><td><code>aaaaa</code></td><td>aaaa + everything else; slow, last resort</td></tr><tr><td><code>af</code></td><td>analyse function at current/given address</td></tr><tr><td><code>afr</code></td><td>analyse function recursively (follow all called functions)</td></tr><tr><td><code>aac</code></td><td>analyse all calls (find call sites you missed)</td></tr><tr><td><code>aar</code></td><td>analyse all references (data and code)</td></tr><tr><td><code>aap</code></td><td>analyse all preludes (find functions by recognising entry sequences)</td></tr><tr><td><code>aae</code></td><td>analyse all by ESIL emulation</td></tr><tr><td><code>ad</code></td><td>analyse data (find structures, arrays)</td></tr><tr><td><code>ac</code></td><td>classify (auto-set function types from references)</td></tr></tbody></table><p>For most well-formed binaries, <code>aaa</code> is the right level. For raw firmware without symbols, <code>aaaa</code> finds more functions but is more likely to invent ones that are not real.</p><h2 id="a-safe-analysis-recipe" tabindex="-1">A safe analysis recipe <a class="header-anchor" href="#a-safe-analysis-recipe" aria-label="Permalink to &quot;A safe analysis recipe&quot;">​</a></h2><p>Default recipe — works for ELFs, Mach-Os, and most well-formed firmware:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; aaa</span></span></code></pre></div><p>That is it. You then read the result with:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; afl              # list functions</span></span>
<span class="line"><span>[0x00]&gt; afl ~ main       # filter</span></span>
<span class="line"><span>[0x00]&gt; aflc             # function call counts</span></span>
<span class="line"><span>[0x00]&gt; agf              # ASCII call graph for current function</span></span>
<span class="line"><span>[0x00]&gt; agC              # call graph for whole binary (huge, dump to file)</span></span></code></pre></div><p>For firmware blobs, the recipe needs more care because there is no entry-point list to seed analysis from. Build it up:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; e anal.from = 0x08000000     # restrict analysis to flash</span></span>
<span class="line"><span>[0x00]&gt; e anal.to   = 0x08100000</span></span>
<span class="line"><span>[0x00]&gt; e anal.depth = 64            # how deep to recurse on calls</span></span>
<span class="line"><span>[0x00]&gt; aap                          # find functions by prelude pattern</span></span>
<span class="line"><span>[0x00]&gt; aac                          # find more by examining call sites</span></span>
<span class="line"><span>[0x00]&gt; aar                          # propagate references</span></span>
<span class="line"><span>[0x00]&gt; aaft                         # propagate types (BB-level)</span></span></code></pre></div><p><code>aap</code> is the workhorse for stripped firmware. It scans the loaded sections for known function preludes (e.g., ARM Thumb <code>push {..., lr}</code>, MIPS <code>addiu sp, sp, -N</code>, RISC-V <code>addi sp, sp, -N</code>) and creates function boundaries at every match. It is fast and usually correct.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>On architectures where <code>aap</code> does not have good preludes (8051, AVR, some Xtensa builds), it finds nothing. Fall back to <code>aac</code> (call-target discovery), which seeds functions from the destinations of <code>call</code>-class instructions. See the relevant Part III chapter.</p></div><h2 id="important-anal-knobs" tabindex="-1">Important <code>anal.*</code> knobs <a class="header-anchor" href="#important-anal-knobs" aria-label="Permalink to &quot;Important \`anal.*\` knobs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>anal.depth</code></td><td>16</td><td>recursion depth when following calls. Raise to 64 for deep firmware</td></tr><tr><td><code>anal.bb.maxsize</code></td><td>4096</td><td>max basic block size. Raise if you have huge unrolled loops</td></tr><tr><td><code>anal.fcn.maxsize</code></td><td>0x100000</td><td>max function size. Lower if r2 merges two functions together</td></tr><tr><td><code>anal.hasnext</code></td><td>false</td><td>continue after function end if next bytes look like code</td></tr><tr><td><code>anal.from / to</code></td><td>-1</td><td>restrict analysis address range</td></tr><tr><td><code>anal.in</code></td><td>io.maps</td><td>scope (<code>io.maps</code>, <code>dbg.map</code>, <code>bin.section</code>, …)</td></tr><tr><td><code>anal.jmp.tbl</code></td><td>true</td><td>recover jump tables (essential for switch statements)</td></tr><tr><td><code>anal.jmp.indir</code></td><td>true</td><td>follow indirect jumps via ESIL</td></tr><tr><td><code>anal.calls</code></td><td>true</td><td>mark function calls during prelude analysis</td></tr><tr><td><code>anal.cc</code></td><td>(arch)</td><td>calling convention for new functions</td></tr><tr><td><code>anal.armthumb</code></td><td>true</td><td>distinguish ARM and Thumb during analysis</td></tr></tbody></table><p>The two that bite most often are <code>anal.depth</code> (too low and call graphs look truncated) and <code>anal.in</code> (too broad and r2 wastes minutes scanning unmapped regions). For ROM-only firmware, set <code>anal.in = io.maps</code> and restrict <code>anal.from</code>/<code>anal.to</code> to your code section.</p><h2 id="reading-the-analysis-output" tabindex="-1">Reading the analysis output <a class="header-anchor" href="#reading-the-analysis-output" aria-label="Permalink to &quot;Reading the analysis output&quot;">​</a></h2><p>After analysis, the things you want to look at first:</p><p><strong>Function list:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; afl</span></span>
<span class="line"><span>0x080001cd    1 18           reset_handler</span></span>
<span class="line"><span>0x080001df    1 12           default_handler</span></span>
<span class="line"><span>0x080001eb    4 40           sym.SystemInit</span></span>
<span class="line"><span>0x08000213    8 124   -&gt; 116 sym.main</span></span>
<span class="line"><span>0x0800028f    1 14           sym.HAL_GPIO_Init</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>Columns: address, basic block count, total size (<code>-&gt; N</code> shows decompiled size if smaller), name. Sort by <code>aflj</code> and pipe to <code>jq</code> if you need something specific.</p><p><strong>Strings:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; izz       # all strings (entire binary, not just sections)</span></span>
<span class="line"><span>[0x00]&gt; iz        # strings in data sections only</span></span></code></pre></div><p>For embedded the difference matters: <code>iz</code> misses strings that live in flash without being in a recognised data section, which is most of them. Use <code>izz</code> and live with the false positives.</p><p><strong>Imports:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; ii        # imported symbols (libc functions etc., for ELFs)</span></span></code></pre></div><p>Mostly empty for bare-metal firmware. Useful for Linux userland on Cortex-A.</p><p><strong>Cross-references:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; axt @ sym.main             # what calls main?</span></span>
<span class="line"><span>[0x00]&gt; axf @ sym.main             # what does main reference?</span></span>
<span class="line"><span>[0x00]&gt; ax                         # all xrefs in the database</span></span></code></pre></div><p><code>axt</code> (xrefs <em>to</em> this address) is the single most useful command for following control flow backwards. Combine with iteration:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00]&gt; pdf @@= \`axt @ sym.imp.printf ~[1]\`   # disasm every printf caller</span></span></code></pre></div><h2 id="function-recovery-problems-and-how-to-spot-them" tabindex="-1">Function recovery problems and how to spot them <a class="header-anchor" href="#function-recovery-problems-and-how-to-spot-them" aria-label="Permalink to &quot;Function recovery problems and how to spot them&quot;">​</a></h2><p>Real binaries trip up analysis. Watch for these patterns:</p><p><strong>One enormous function.</strong> Two real functions got merged because the boundary between them looked like a tail call. Check with <code>afl ~ </code> and look for a function with implausible size. Fix:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; af-                        # delete the function</span></span>
<span class="line"><span>[0x...]&gt; af @ 0x08001234            # recreate at the correct entry</span></span></code></pre></div><p><strong>A function with one basic block and 200 instructions.</strong> A jump table was missed and <code>aap</code> saw the whole linear stretch as one block. Fix:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; ahb 16                     # hint: this is Thumb (if arch confused)</span></span>
<span class="line"><span>[0x...]&gt; af-                        # remove</span></span>
<span class="line"><span>[0x...]&gt; aac                        # rerun call discovery</span></span></code></pre></div><p><strong>Functions that &quot;exist&quot; but contain decode-as-data noise.</strong> <code>aap</code> matched a prelude pattern in literal-pool data. Delete with <code>af-</code> and add <code>Cd 4 @ &lt;addr&gt;</code> to mark those bytes as data, so analysis ignores them.</p><p><strong>Decompilation produces nonsense for one function but works for others.</strong> Almost always a calling-convention mismatch. Set the cc explicitly:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; afc cdecl @ sym.foo        # set calling convention</span></span></code></pre></div><p>Or, on ARM, set the right ABI:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; e anal.cc = arm32</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Tip</p><p><code>aaa</code> is idempotent — running it again will not undo your manual fixes. Combine: load, <code>aaa</code>, fix the obvious problems by hand, run <code>aaa</code> again to propagate the fixes through xrefs.</p></div><h2 id="hints-ah" tabindex="-1">Hints (<code>ah</code>) <a class="header-anchor" href="#hints-ah" aria-label="Permalink to &quot;Hints (\`ah\`)&quot;">​</a></h2><p>When the analysis is wrong about something, you tell r2 with <strong>hints</strong>. Hints attach to addresses and survive re-analysis.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; ahb 16 @ 0x08001234       # bits at this address (Thumb here)</span></span>
<span class="line"><span>[0x...]&gt; ahb 32 @ 0x08001500       # ARM mode (thumb-interworking)</span></span>
<span class="line"><span>[0x...]&gt; aha mov @ 0x...           # treat as MOV (override decode)</span></span>
<span class="line"><span>[0x...]&gt; ahf @ 0x08001234          # this address is a function</span></span>
<span class="line"><span>[0x...]&gt; ahi 10 @ 0x...            # display this immediate as decimal</span></span>
<span class="line"><span>[0x...]&gt; ahi h @ 0x...             # ... as hex</span></span>
<span class="line"><span>[0x...]&gt; ahi b @ 0x...             # ... as binary</span></span>
<span class="line"><span>[0x...]&gt; ahS .text @ 0x...         # set syntax variant</span></span>
<span class="line"><span>[0x...]&gt; ahc 0x08001234            # this byte is the start of a call</span></span></code></pre></div><p>ARM/Thumb interworking is the big use case: a Cortex-M binary with mixed ARM and Thumb code (rare but it happens with TrustZone secure-side code) needs <code>ahb 16</code> and <code>ahb 32</code> hints in the right places, or half the disassembly will be wrong.</p><h2 id="re-running-analysis" tabindex="-1">Re-running analysis <a class="header-anchor" href="#re-running-analysis" aria-label="Permalink to &quot;Re-running analysis&quot;">​</a></h2><p>If you change any <code>anal.*</code> knob, re-run the relevant pass. <code>aaa</code> is expensive on big firmware; for incremental work, use the narrower commands:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x...]&gt; af @ 0x08005000          # just analyse this one function</span></span>
<span class="line"><span>[0x...]&gt; afr @ 0x08005000         # ... and recursively into its callees</span></span>
<span class="line"><span>[0x...]&gt; aac                      # find calls you missed</span></span>
<span class="line"><span>[0x...]&gt; aar                      # data refs only</span></span></code></pre></div><p>For multi-megabyte firmware, the whole <code>aaa</code> run can take minutes; narrow commands run in milliseconds. Save the project (<code>Ps</code>) before running <code>aaaa</code> so you can re-open the saved project (<code>P name</code>, formerly <code>Po name</code>) to roll back to a clean state if it makes things worse.</p><h2 id="when-to-escalate-to-aaaa" tabindex="-1">When to escalate to <code>aaaa</code> <a class="header-anchor" href="#when-to-escalate-to-aaaa" aria-label="Permalink to &quot;When to escalate to \`aaaa\`&quot;">​</a></h2><p><code>aaaa</code> runs additional passes that try to:</p><ul><li>propagate types across calls,</li><li>recover function names from RTTI / vtables,</li><li>find functions that look like noreturn,</li><li>infer signatures from string formatting calls.</li></ul><p>It can take 10× longer than <code>aaa</code> and occasionally renames functions incorrectly. Use it on:</p><ul><li>large stripped C++ binaries,</li><li>binaries with extensive vtable use,</li><li>anywhere you want noreturn detection (it improves graph layout).</li></ul><p>Skip it on:</p><ul><li>small bare-metal firmware (it adds nothing useful),</li><li>anything where the analysis is already correct.</li></ul><h2 id="what-good-looks-like" tabindex="-1">What &quot;good&quot; looks like <a class="header-anchor" href="#what-good-looks-like" aria-label="Permalink to &quot;What &quot;good&quot; looks like&quot;">​</a></h2><p>After analysis, a healthy session looks like:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x08000000]&gt; afl | wc -l</span></span>
<span class="line"><span>347</span></span>
<span class="line"><span>[0x08000000]&gt; afl ~ ?              # functions matching unknown patterns</span></span>
<span class="line"><span>0x08000a40    1 12           fcn.08000a40</span></span>
<span class="line"><span>... (handful, most named or recognisable)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[0x08000000]&gt; agC &gt; /tmp/cg.gv     # full call graph</span></span>
<span class="line"><span>[0x08000000]&gt; !! dot -Tpng /tmp/cg.gv &gt; /tmp/cg.png &amp;&amp; open /tmp/cg.png</span></span></code></pre></div><p>If the call graph has many disconnected islands, r2 missed call edges. Run <code>aac</code> again and re-check. If the count of <code>fcn.*</code>-named functions is large, you have many functions r2 found but did not name from any symbol or string — that is normal for stripped firmware and the next chapters will give you tools to name them.</p>`,64)])])}const m=e(o,[["render",i]]);export{u as __pageData,m as default};
